mapper.select:
SELECT d.device_id, d.project_id, p.project_man, d.factory_device_id, d.device_name, d.insert_time, d.device_type, d.video, d.lng, d.lat, w.water, w.tm AS water_tm, f.flow, f.tm as flow_tm, g.grade, g.tm as grade_tm, d.shortcut d.status FROM device_info d LEFT JOIN project_manage p ON d.project_id = p.project_id left JOIN grade_realtime g ON d.factory_device_id = g.factory_device_id LEFT JOIN flow_realtime f ON d.factory_device_id = f.factory_device_id LEFT JOIN water_realtime w ON d.factory_device_id = w.factory_device_id WHERE d.deleted = 0 and d.factory_device_id IS NOT NULL
AND d.project_id = #{reqVO.projectId}
AND d.device_name LIKE CONCAT(CONCAT('%', #{reqVO.deviceName}), '%')
